import yaml, re, sys
p='.coordination/mining/v2/day-002.yaml'
d=yaml.safe_load(open(p))
raw=open('claude-dev-log-diary/day-002.md').read().replace('\xa0',' ')
srclines=[l.rstrip('\n').replace('\xa0',' ') for l in open('claude-dev-log-diary/day-002.md')]
flat=re.sub(r'\s+',' ',raw)
bad=[]
def norm(s): return re.sub(r'\s+',' ',s).strip()
def check(q, where):
    if q is None: return
    parts=q.replace('\xa0',' ').split('\n')
    idxs=[]
    for part in parts:
        found=[i for i,l in enumerate(srclines) if part in l]
        if not found: idxs.append(None)
        else: idxs.append(found)
    if all(idxs):
        if len(parts)==1: return
        if any(all((s+k) in idxs[k] for k in range(len(parts))) for s in idxs[0]): return
    # fallback: whitespace-normalized presence of the whole quote (console wrap reconstruction)
    if norm(q) in flat: 
        print("  [wrap-join OK]", where, '::', norm(q)[:60]); return
    bad.append((where,'UNVERIFIED: '+parts[0][:70]))
for sec in ('philosophy','skill_rules','failure_modes','pairing_rules'):
    for it in d.get(sec,[]):
        check(it.get('quote'), sec+':'+str(it.get('rule_id') or it.get('name') or it.get('loc')))
print("UNVERIFIED QUOTES:", len(bad))
for b in bad: print("  ",b)
print("SECTIONS:", {k:(len(v) if isinstance(v,list) else 1) for k,v in d.items()})
